import React, { useState, useContext } from "react";
import Layout, { SectionContext } from "./components/Layout";
import Dashboard from "./components/Dashboard";
import GoalForm from "./components/GoalForm";
import Overview from "./components/Overview";
import GoalWizard from "./components/GoalWizard";

const API_URL = "http://localhost:3001/api/plans/calculate";

function getMonthsRemaining(deadline) {
  const now = new Date();
  const end = new Date(deadline);
  return Math.max(
    1,
    (end.getFullYear() - now.getFullYear()) * 12 + (end.getMonth() - now.getMonth())
  );
}

function getMonthlySavings(goal) {
  if (goal.monthlySavings && goal.monthlySavings !== 0) return goal.monthlySavings;
  const months = getMonthsRemaining(goal.deadline);
  const amountLeft = Math.max(goal.amount - (goal.saved || 0), 0);
  return +(amountLeft / months).toFixed(2);
}

const AppContent = ({ income, setIncome }) => {
  const { activeSection, setActiveSection } = useContext(SectionContext);
  const [goals, setGoals] = useState([]);
  const [showGoalForm, setShowGoalForm] = useState(false);
  const [showGoalWizard, setShowGoalWizard] = useState(false);
  const [editGoal, setEditGoal] = useState(null);
  const [plan, setPlan] = useState({ goals: [], totalMonthlyNeeded: 0, disposableIncome: 0 });
  const [sortBy, setSortBy] = useState("priority");

  React.useEffect(() => {
    if (goals.length === 0 || !income) {
      setPlan({ goals, totalMonthlyNeeded: 0, disposableIncome: income });
      return;
    }
    fetch(API_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ goals, disposableIncome: income }),
    })
      .then((res) => res.json())
      .then((data) => setPlan(data))
      .catch(() => setPlan({ goals, totalMonthlyNeeded: 0, disposableIncome: income }));
  }, [goals, income]);

  const addGoal = (goal) => {
    setGoals((prev) => [...prev, goal]);
  };

  const removeGoal = (id) => {
    setGoals((prev) => prev.filter((g) => g.id !== id));
  };

  const handleEditGoal = (goal) => {
    setEditGoal(goal);
    setShowGoalForm(true);
  };

  const handleSaveGoal = (goal) => {
    if (editGoal) {
      setGoals((prev) => prev.map((g) => (g.id === goal.id ? goal : g)));
      setEditGoal(null);
    } else {
      addGoal(goal);
    }
    setShowGoalForm(false);
    setShowGoalWizard(false);
  };

  // Sort goals by priority, deadline soonest, or deadline furthest
  const sortedGoals = [...(plan.goals.length ? plan.goals : goals)].sort((a, b) => {
    if (sortBy === "priority") {
      return (a.priority || 0) - (b.priority || 0);
    } else if (sortBy === "deadline-soonest") {
      return new Date(a.deadline) - new Date(b.deadline);
    } else if (sortBy === "deadline-furthest") {
      return new Date(b.deadline) - new Date(a.deadline);
    }
    return 0;
  });

  // Always recalculate totalMonthlyNeeded for the currently displayed goals
  const totalMonthlyNeeded = sortedGoals.reduce((sum, g) => sum + getMonthlySavings(g), 0);

  let content;
  if (activeSection === "home" || activeSection === "goals") {
    content = (
      <Dashboard
        goals={sortedGoals}
        income={income}
        onRemoveGoal={removeGoal}
        onShowGoalForm={() => setShowGoalForm(true)}
        onEditGoal={handleEditGoal}
        totalMonthlyNeeded={totalMonthlyNeeded}
        sortBy={sortBy}
        setSortBy={setSortBy}
        onShowGoalWizard={() => setShowGoalWizard(true)}
        setGoals={setGoals}
      />
    );
  } else if (activeSection === "overview") {
    content = <Overview goals={sortedGoals} income={income} />;
  } else if (activeSection === "goalwizard") {
    content = (
      <GoalWizard
        onClose={() => setActiveSection("goals")}
        onAddGoal={handleSaveGoal}
      />
    );
  }

  return (
    <>
      {content}
      {showGoalForm && (
        <GoalForm
          onClose={() => {
            setShowGoalForm(false);
            setEditGoal(null);
          }}
          onAddGoal={handleSaveGoal}
          editGoal={editGoal}
        />
      )}
      {showGoalWizard && (
        <GoalWizard
          onClose={() => setShowGoalWizard(false)}
          onAddGoal={handleSaveGoal}
        />
      )}
    </>
  );
};

const App = () => {
  const [income, setIncome] = useState(0);
  return (
    <Layout income={income} setIncome={setIncome}>
      <AppContent income={income} setIncome={setIncome} />
    </Layout>
  );
};

export default App;
